const totalDots = 30;//also change the BALL_AMOUNT in Shader tab

let organize = false;
const changeTime = 120;
let lastFrameChangeTime = 0;

let dots = [];
let size;

let prevRotateAngle = 0, destRotateAngle = 0, rotateAngle = 0;

let sha;//Shader Tab

function setup() {
	size = max(windowWidth, windowHeight);
	let renderer = createCanvas(size, size, WEBGL);
	background(0);
	pixelDensity(1);
  //ortho(-width / 2, width / 2, -height / 2, height / 2, 0, 1000);
  for(let i = 0; i < totalDots; i++){
		dots.push({
			counter: random(1000),
			pos: createVector(),
			destPos: createVector(),
			velocity: random(0.005, 0.01),
			step: random(1000),
			size: random(5, 50),
			sizeSinStep: random(1000)
		});
  }

	sha = new p5.Shader(canvas._renderer, vert, frag);
}

function draw() {
  let tempOrganize = frameCount%(changeTime*2)>changeTime;
  if(organize!=tempOrganize){
    lastFrameChangeTime = frameCount;
    organize = tempOrganize;
    prevRotateAngle = rotateAngle;
    if(organize) destRotateAngle += PI/2;
  }

  let easeLerp = easeInOutQuint((frameCount - lastFrameChangeTime) / changeTime);
  rotateAngle = lerp(prevRotateAngle, destRotateAngle, easeLerp);

  let posX = new Array(totalDots);
  let posY = new Array(totalDots);
  let posZ = new Array(totalDots);
  let sizes = new Array(totalDots);
  for(let i = 0; i < dots.length; i++){
		//calculate dot position
		if(organize){
      dots[i].destPos.x = (round(dots[i].pos.x / size * 2) * size / 2);
      dots[i].destPos.y = (round(dots[i].pos.y / size * 2) * size / 2);
      dots[i].destPos.z = (round(dots[i].pos.z / size * 2) * size / 2);
			//avoid dots in center
      if(dots[i].destPos.x == 0 && dots[i].destPos.y == 0 && dots[i].destPos.z == 0){
        dots[i].destPos.x = size / 2 * Math.sign(dots[i].pos.x);
        dots[i].destPos.y = size / 2 * Math.sign(dots[i].pos.y);
        dots[i].destPos.z = size / 2 * Math.sign(dots[i].pos.z);
      }
    }else{
      dots[i].counter += dots[i].velocity;
      dots[i].destPos.x = (noise(dots[i].counter * 0.5 + dots[i].step) - 0.5) * size * 2;
      dots[i].destPos.y = (noise(dots[i].counter * 0.3 + dots[i].step) - 0.5) * size * 2;
      dots[i].destPos.z = (noise(dots[i].counter * 0.1 + dots[i].step) - 0.5) * size * 2;
    }
    dots[i].pos.x += (dots[i].destPos.x - dots[i].pos.x) * 0.05;
    dots[i].pos.y += (dots[i].destPos.y - dots[i].pos.y) * 0.05;
    dots[i].pos.z += (dots[i].destPos.z - dots[i].pos.z) * 0.05;
    dots[i].sizeSin = abs(sin(frameCount / 100 + dots[i].sizeSinStep) * dots[i].size) + 5;

		//transfer processing unity to shader unity
    posX[i] = dots[i].pos.x / size * 3;
    posY[i] = dots[i].pos.y / size * 3;
    posZ[i] = dots[i].pos.z / size * 3;
    sizes[i] = dots[i].sizeSin / 200;
  }

	sha.setUniform("resolution", [width, height]);
  sha.setUniform("time", millis() / 1000.0);
  sha.setUniform("mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))]);
  sha.setUniform("posX", posX);
  sha.setUniform("posY", posY);
  sha.setUniform("posZ", posZ);
  sha.setUniform("size", sizes);
  sha.setUniform("rotate", rotateAngle);
  sha.setUniform("intensity", map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 0.01, 6, true));
  shader(sha);

  fill(255);
  rect(0, 0, width, height);
}

function easeInOutQuint(t) {
  return t < 0.5 ? 16*t*t*t*t*t : 1+16*(--t)*t*t*t*t;
}

